package com.loadoutstudio;
import com.google.gson.*;
import java.util.*;
import javax.swing.*;
import java.awt.*;
import java.awt.event.MouseEvent;
import java.awt.event.InputEvent;
import org.junit.Test;
import net.runelite.api.gameval.ItemID;
import net.runelite.http.api.RuneLiteAPI;
import static org.junit.Assert.*;
public class PlayerFeedbackTest {
 @Test public void ultorUsesRealGameItemEvenWhenAnOlderSameNameDefinitionExists(){ItemCatalogue c=new ItemCatalogue();c.add(100,"Ultor ring",false,-1,-1,12,false,false);c.add(ItemID.ULTOR_RING,"Ultor ring",false,-1,-1,12,true,true);c.add(ItemID.BR_ULTOR_RING,"Ultor ring",false,-1,-1,12,true,true);assertEquals(ItemID.ULTOR_RING,c.firstExact("Ultor ring").id);assertFalse(c.search("Ultor ring").stream().anyMatch(i->i.id==ItemID.BR_ULTOR_RING));}
 @Test public void realEquipmentMetadataBeatsAnUnusableSameNameCopy(){ItemCatalogue c=new ItemCatalogue();c.add(10,"Fixture helm",false,-1,-1,-1,false,false);c.add(20,"Fixture helm",false,-1,-1,0,true,true);assertEquals(20,c.firstExact("Fixture helm").id);assertEquals(0,c.firstExact("Fixture helm").slot);}
 @Test public void nestedWikiItemsAndTabletAliasesResolveNames(){assertEquals("Teleport to house",WikiParser.itemName("{{Item|Teleport to house (tablet)}}"));assertEquals("Nature rune",WikiParser.itemName("{{Rune|Nature}}"));assertEquals("Ultor ring",WikiParser.itemName("{{plink|Ultor ring}}"));}
 @Test public void activitySuggestionsHideTechnicalPagesAndDeduplicateStrategies(){assertEquals(Arrays.asList("Vorkath","Fractured archive"),WikiClient.activityTitles(Arrays.asList("Vorkath","Vorkath/Strategies","Vorkath's head","Fractured archive table","Fractured archive miniquest","Fractured archive strategies")));}
 @Test public void sourceHeadersReplaceStyleAttributesAndKeepNamedVariants(){String wiki="{| class=\"wikitable\"\n! Max gear !! Mid-game\n|-\n| {{Equipment|head=Torva full helm}}{{Inventory|1=Shark}}\n| {{Equipment|head=Helm of neitiznot}}{{Inventory|1=Shark}}\n|}";java.util.List<JsonObject> p=new WikiParser().parse(wiki,"Boss/Strategies","Fixture");assertEquals("Max gear",WikiParser.variant(p.get(0)));assertEquals("Mid-game",WikiParser.variant(p.get(1)));assertEquals("Boss (Mid-game)",SetupCodec.name(p.get(1)));assertFalse(SetupCodec.name(p.get(0)).contains("class="));}
 @Test public void duplicateNamesAreNumberedWithoutChangingExistingNames(){SetupLibrary l=new SetupLibrary();l.setups.add(new SetupLibrary.Entry(SetupCodec.blank("Boss")));assertEquals("Boss (1)",l.uniqueName("Boss"));l.setups.add(new SetupLibrary.Entry(SetupCodec.blank("Boss (1)")));assertEquals("Boss (2)",l.uniqueName("Boss"));String longName="A".repeat(50);l.setups.add(new SetupLibrary.Entry(SetupCodec.blank(longName)));assertEquals(50,l.uniqueName(longName).length());}
 @Test public void alternativesUseRankedCompatibleGroupsInsteadOfEverySameSlot(){Map<Integer,Integer> amounts=new LinkedHashMap<>();Map<Integer,StudioPanel.ItemInfo> items=new LinkedHashMap<>();items.put(1,new StudioPanel.ItemInfo(1,"Torva platebody",false,4,null));items.put(3,new StudioPanel.ItemInfo(3,"Fighter torso",false,4,null));items.put(2,new StudioPanel.ItemInfo(2,"Bandos chestplate",false,4,null));items.put(4,new StudioPanel.ItemInfo(4,"Ancestral robe top",false,4,null));amounts.put(3,1);amounts.put(2,1);amounts.put(4,1);JsonObject p=SetupCodec.blank("Melee");SetupCodec.setup(p).getAsJsonArray("eq").set(4,SetupCodec.item(1,1));java.util.List<OwnedGear.Proposal> choices=new OwnedGear(amounts,items,1,true).alternatives(p,n->null);assertEquals(2,choices.get(0).choices.size());assertEquals(2,choices.get(0).choices.get(0).id);assertEquals(3,choices.get(0).choices.get(1).id);}
 @Test public void bankPlanPreservesSourceIndicesAndNeverMutatesItemIds(){int[] ids={10,20,30},before=ids.clone();int[] layout={30,-1,10,-1,20};assertArrayEquals(new int[]{2,4,0},BankViewPlan.positions(ids,layout,id->id));assertArrayEquals(before,ids);int[] stack={99,10};BankViewPlan.callback("bankSearchFilter",stack,2,id->id==20);assertEquals(0,stack[0]);assertEquals(10,stack[1]);BankViewPlan.callback("bankBuildTab",stack,2,id->true);assertEquals(1,stack[1]);}
 @Test public void setupToolbarTogglesHighlightingAndShiftMenuUsesAllSetups() throws Exception {SwingUtilities.invokeAndWait(()->{PanelTest.FakeHost host=new PanelTest.FakeHost();StudioPanel p=new StudioPanel(host,RuneLiteAPI.GSON);JsonObject setup=SetupCodec.blank("Toolbar");SetupCodec.setup(setup).getAsJsonArray("inv").set(0,SetupCodec.item(560,1));p.newDraft(setup);assertNotNull(OwnedGearPanelTest.find(p,"setupActions"));OwnedGearPanelTest.click(p,"setupToggle:highlight");OwnedGearPanelTest.click(p,"Save");assertFalse(SetupCodec.setup(SetupLibrary.read(host.saved,RuneLiteAPI.GSON).setups.get(0).portable).get("hd").getAsBoolean());OwnedGearPanelTest.click(p,"setupToggle:unordered");OwnedGearPanelTest.click(p,"Save");assertTrue(SetupCodec.setup(SetupLibrary.read(host.saved,RuneLiteAPI.GSON).setups.get(0).portable).get("uh").getAsBoolean());JButton slot=slot(p);slot.dispatchEvent(new MouseEvent(slot,MouseEvent.MOUSE_PRESSED,System.currentTimeMillis(),InputEvent.SHIFT_DOWN_MASK,2,2,1,false,MouseEvent.BUTTON3));boolean found=false;for(Component c:slot.getComponentPopupMenu().getComponents())if(c instanceof JMenuItem&&((JMenuItem)c).getText().equals("Update ALL slots from Search"))found=true;assertTrue(found);p.dispose();});}
 private static JButton slot(Container root){for(Component c:root.getComponents()){if(c instanceof JButton&&"inv".equals(((JButton)c).getClientProperty("slotContainer"))&&Integer.valueOf(0).equals(((JButton)c).getClientProperty("slotIndex")))return (JButton)c;if(c instanceof Container){JButton b=slot((Container)c);if(b!=null)return b;}}return null;}
}
